const domain = items[0].json.domain;
const gscProperty = items[0].json.gsc_property;
const apiKey = "YOUR_GOOGLE_API_KEY";
const now = new Date();

// YoY — last 3 full months vs same period last year
const endDate = new Date(now.getFullYear(), now.getMonth(), 0);
const startDate = new Date(endDate.getFullYear(), endDate.getMonth() - 2, 1);
const endDateLY = new Date(endDate.getFullYear() - 1, endDate.getMonth(), endDate.getDate());
const startDateLY = new Date(startDate.getFullYear() - 1, startDate.getMonth(), startDate.getDate());

// QoQ — previous 3 full months (the 3 months before the current period)
const endDateQoQ = new Date(startDate.getFullYear(), startDate.getMonth(), 0);
const startDateQoQ = new Date(endDateQoQ.getFullYear(), endDateQoQ.getMonth() - 2, 1);

// MoM — last full month vs the month before
const endDateMoM = new Date(now.getFullYear(), now.getMonth(), 0);
const startDateMoM = new Date(endDateMoM.getFullYear(), endDateMoM.getMonth(), 1);
const endDateMoMPrev = new Date(startDateMoM.getFullYear(), startDateMoM.getMonth(), 0);
const startDateMoMPrev = new Date(endDateMoMPrev.getFullYear(), endDateMoMPrev.getMonth(), 1);

const fmt = (d) => d.toISOString().split('T')[0];

return [{
  json: {
    client_name: items[0].json.client_name,
    domain: domain,
    ga_property_id: items[0].json.ga_property_id,
    gsc_property: gscProperty,
    accuranker_domain_id: items[0].json.accuranker_domain_id,
    inspection_url: gscProperty,
    pagespeed_mobile_url: "https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=https://" + domain + "&strategy=mobile&key=" + apiKey,
    pagespeed_desktop_url: "https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=https://" + domain + "&strategy=desktop&key=" + apiKey,
    baseUrl: "https://" + domain,

    // YoY
    period_a_start: fmt(startDate),
    period_a_end: fmt(endDate),
    period_b_start: fmt(startDateLY),
    period_b_end: fmt(endDateLY),

    // QoQ
    period_qoq_start: fmt(startDateQoQ),
    period_qoq_end: fmt(endDateQoQ),

    // MoM
    period_mom_start: fmt(startDateMoM),
    period_mom_end: fmt(endDateMoM),
    period_mom_prev_start: fmt(startDateMoMPrev),
    period_mom_prev_end: fmt(endDateMoMPrev)
  }
}];

