parameters.jsCode:
const items_data = $input.all().map(i => i.json);

const getMetric = (rows, period, metricIndex) => {
  const row = rows.find(r => r.dimensionValues.some(d => d.value === period));
  return row ? parseFloat(row.metricValues[metricIndex].value) : 0;
};

const getMetricByDim = (rows, dimValue, period, metricIndex) => {
  const row = rows.find(r =>
    r.dimensionValues.some(d => d.value === dimValue) &&
    r.dimensionValues.some(d => d.value === period)
  );
  return row ? parseFloat(row.metricValues[metricIndex].value) : 0;
};

const allStandard = items_data.filter(i => i.metricHeaders?.some(h => h.name === 'newUsers'));
const allOrganic = items_data.filter(i => 
  i.metricHeaders?.some(h => h.name === 'sessions') && 
  i.metricHeaders?.some(h => h.name === 'userEngagementDuration') &&
  !i.metricHeaders?.some(h => h.name === 'newUsers')
);
const allClicks = items_data.filter(i => i.metricHeaders?.some(h => h.name === 'eventCount'));

const hasPeriodB = (item) => item.rows?.some(r => r.dimensionValues.some(d => d.value === 'period_b'));

const standardYoY = allStandard.find(i => hasPeriodB(i)) || {};
const standardQMM = allStandard.find(i => !hasPeriodB(i)) || {};
const organicYoY = allOrganic.find(i => hasPeriodB(i)) || {};
const organicQMM = allOrganic.find(i => !hasPeriodB(i)) || {};
const clicksYoY = allClicks.find(i => hasPeriodB(i)) || {};
const clicksQMM = allClicks.find(i => !hasPeriodB(i)) || {};

const sYoY = standardYoY.rows || [];
const sQMM = standardQMM.rows || [];
const oYoY = organicYoY.rows || [];
const oQMM = organicQMM.rows || [];
const cYoY = clicksYoY.rows || [];
const cQMM = clicksQMM.rows || [];

// Standard — YoY
const sessions_a = getMetric(sYoY, 'period_a', 0);
const sessions_b = getMetric(sYoY, 'period_b', 0);
const engagementDuration_a = getMetric(sYoY, 'period_a', 1);
const engagementDuration_b = getMetric(sYoY, 'period_b', 1);
const newUsers_a = getMetric(sYoY, 'period_a', 2);
const newUsers_b = getMetric(sYoY, 'period_b', 2);
const keyEvents_a = getMetric(sYoY, 'period_a', 3);
const keyEvents_b = getMetric(sYoY, 'period_b', 3);

// Standard — QoQ
const sessions_qoq = getMetric(sQMM, 'period_qoq', 0);
const engagementDuration_qoq = getMetric(sQMM, 'period_qoq', 1);
const newUsers_qoq = getMetric(sQMM, 'period_qoq', 2);
const keyEvents_qoq = getMetric(sQMM, 'period_qoq', 3);

// Standard — MoM
const sessions_mom = getMetric(sQMM, 'period_mom', 0);
const sessions_mom_prev = getMetric(sQMM, 'period_mom_prev', 0);
const engagementDuration_mom = getMetric(sQMM, 'period_mom', 1);
const engagementDuration_mom_prev = getMetric(sQMM, 'period_mom_prev', 1);
const newUsers_mom = getMetric(sQMM, 'period_mom', 2);
const newUsers_mom_prev = getMetric(sQMM, 'period_mom_prev', 2);
const keyEvents_mom = getMetric(sQMM, 'period_mom', 3);
const keyEvents_mom_prev = getMetric(sQMM, 'period_mom_prev', 3);

// Organic — YoY
const organicSessions_a = getMetricByDim(oYoY, 'Organic Search', 'period_a', 0);
const organicSessions_b = getMetricByDim(oYoY, 'Organic Search', 'period_b', 0);
const organicEngagement_a = getMetricByDim(oYoY, 'Organic Search', 'period_a', 1);
const organicEngagement_b = getMetricByDim(oYoY, 'Organic Search', 'period_b', 1);
const organicEngagedSessions_a = getMetricByDim(oYoY, 'Organic Search', 'period_a', 3);
const organicEngagedSessions_b = getMetricByDim(oYoY, 'Organic Search', 'period_b', 3);
const organicEngagementRate_a = organicSessions_a > 0 ? ((organicEngagedSessions_a / organicSessions_a) * 100).toFixed(1) : 0;
const organicEngagementRate_b = organicSessions_b > 0 ? ((organicEngagedSessions_b / organicSessions_b) * 100).toFixed(1) : 0;

// *** Organic Key Events — YoY ***
const organicKeyEvents_a = getMetricByDim(oYoY, 'Organic Search', 'period_a', 2);
const organicKeyEvents_b = getMetricByDim(oYoY, 'Organic Search', 'period_b', 2);

// Organic — QoQ
const organicSessions_qoq = getMetricByDim(oQMM, 'Organic Search', 'period_qoq', 0);
const organicEngagement_qoq = getMetricByDim(oQMM, 'Organic Search', 'period_qoq', 1);
const organicEngagedSessions_qoq = getMetricByDim(oQMM, 'Organic Search', 'period_qoq', 3);
const organicEngagementRate_qoq = organicSessions_qoq > 0 ? ((organicEngagedSessions_qoq / organicSessions_qoq) * 100).toFixed(1) : 0;

// *** Organic Key Events — QoQ ***
const organicKeyEvents_qoq = getMetricByDim(oQMM, 'Organic Search', 'period_qoq', 2);

// Organic — MoM
const organicSessions_mom = getMetricByDim(oQMM, 'Organic Search', 'period_mom', 0);
const organicSessions_mom_prev = getMetricByDim(oQMM, 'Organic Search', 'period_mom_prev', 0);
const organicEngagement_mom = getMetricByDim(oQMM, 'Organic Search', 'period_mom', 1);
const organicEngagement_mom_prev = getMetricByDim(oQMM, 'Organic Search', 'period_mom_prev', 1);
const organicEngagedSessions_mom = getMetricByDim(oQMM, 'Organic Search', 'period_mom', 3);
const organicEngagedSessions_mom_prev = getMetricByDim(oQMM, 'Organic Search', 'period_mom_prev', 3);
const organicEngagementRate_mom = organicSessions_mom > 0 ? ((organicEngagedSessions_mom / organicSessions_mom) * 100).toFixed(1) : 0;
const organicEngagementRate_mom_prev = organicSessions_mom_prev > 0 ? ((organicEngagedSessions_mom_prev / organicSessions_mom_prev) * 100).toFixed(1) : 0;

// *** Organic Key Events — MoM ***
const organicKeyEvents_mom = getMetricByDim(oQMM, 'Organic Search', 'period_mom', 2);
const organicKeyEvents_mom_prev = getMetricByDim(oQMM, 'Organic Search', 'period_mom_prev', 2);

// Clicks — YoY
const phoneClicks_a = getMetricByDim(cYoY, 'phone_number_click', 'period_a', 0);
const phoneClicks_b = getMetricByDim(cYoY, 'phone_number_click', 'period_b', 0);
const emailClicks_a = getMetricByDim(cYoY, 'email_address_click', 'period_a', 0);
const emailClicks_b = getMetricByDim(cYoY, 'email_address_click', 'period_b', 0);
const whatsappClicks_a = getMetricByDim(cYoY, 'WhatsApp_Button_Click', 'period_a', 0) + getMetricByDim(cYoY, 'Whatsapp_click', 'period_a', 0);
const whatsappClicks_b = getMetricByDim(cYoY, 'WhatsApp_Button_Click', 'period_b', 0) + getMetricByDim(cYoY, 'Whatsapp_click', 'period_b', 0);

// Clicks — QoQ
const phoneClicks_qoq = getMetricByDim(cQMM, 'phone_number_click', 'period_qoq', 0);
const emailClicks_qoq = getMetricByDim(cQMM, 'email_address_click', 'period_qoq', 0);
const whatsappClicks_qoq = getMetricByDim(cQMM, 'WhatsApp_Button_Click', 'period_qoq', 0) + getMetricByDim(cQMM, 'Whatsapp_click', 'period_qoq', 0);

// Clicks — MoM
const phoneClicks_mom = getMetricByDim(cQMM, 'phone_number_click', 'period_mom', 0);
const phoneClicks_mom_prev = getMetricByDim(cQMM, 'phone_number_click', 'period_mom_prev', 0);
const emailClicks_mom = getMetricByDim(cQMM, 'email_address_click', 'period_mom', 0);
const emailClicks_mom_prev = getMetricByDim(cQMM, 'email_address_click', 'period_mom_prev', 0);
const whatsappClicks_mom = getMetricByDim(cQMM, 'WhatsApp_Button_Click', 'period_mom', 0) + getMetricByDim(cQMM, 'Whatsapp_click', 'period_mom', 0);
const whatsappClicks_mom_prev = getMetricByDim(cQMM, 'WhatsApp_Button_Click', 'period_mom_prev', 0) + getMetricByDim(cQMM, 'Whatsapp_click', 'period_mom_prev', 0);

// Derived metrics
const organicPct_a = sessions_a > 0 ? ((organicSessions_a / sessions_a) * 100).toFixed(1) : 0;
const organicPct_b = sessions_b > 0 ? ((organicSessions_b / sessions_b) * 100).toFixed(1) : 0;
const organicPct_qoq = sessions_qoq > 0 ? ((organicSessions_qoq / sessions_qoq) * 100).toFixed(1) : 0;
const organicPct_mom = sessions_mom > 0 ? ((organicSessions_mom / sessions_mom) * 100).toFixed(1) : 0;
const organicPct_mom_prev = sessions_mom_prev > 0 ? ((organicSessions_mom_prev / sessions_mom_prev) * 100).toFixed(1) : 0;

const avgEngagementTime_a = sessions_a > 0 ? (engagementDuration_a / sessions_a).toFixed(0) : 0;
const avgEngagementTime_b = sessions_b > 0 ? (engagementDuration_b / sessions_b).toFixed(0) : 0;
const avgEngagementTime_qoq = sessions_qoq > 0 ? (engagementDuration_qoq / sessions_qoq).toFixed(0) : 0;
const avgEngagementTime_mom = sessions_mom > 0 ? (engagementDuration_mom / sessions_mom).toFixed(0) : 0;
const avgEngagementTime_mom_prev = sessions_mom_prev > 0 ? (engagementDuration_mom_prev / sessions_mom_prev).toFixed(0) : 0;

const avgOrganicEngagementTime_a = organicSessions_a > 0 ? (organicEngagement_a / organicSessions_a).toFixed(0) : 0;
const avgOrganicEngagementTime_b = organicSessions_b > 0 ? (organicEngagement_b / organicSessions_b).toFixed(0) : 0;
const avgOrganicEngagementTime_qoq = organicSessions_qoq > 0 ? (organicEngagement_qoq / organicSessions_qoq).toFixed(0) : 0;
const avgOrganicEngagementTime_mom = organicSessions_mom > 0 ? (organicEngagement_mom / organicSessions_mom).toFixed(0) : 0;
const avgOrganicEngagementTime_mom_prev = organicSessions_mom_prev > 0 ? (organicEngagement_mom_prev / organicSessions_mom_prev).toFixed(0) : 0;

const pct = (a, b) => b > 0 ? (((a - b) / b) * 100).toFixed(1) : null;


return [{
  json: {
    // Sessions
    sessions_a, sessions_b, sessions_change: pct(sessions_a, sessions_b),
    sessions_qoq, sessions_qoq_change: pct(sessions_a, sessions_qoq),
    sessions_mom, sessions_mom_prev, sessions_mom_change: pct(sessions_mom, sessions_mom_prev),

    // New users
    newUsers_a, newUsers_b, newUsers_change: pct(newUsers_a, newUsers_b),
    newUsers_qoq, newUsers_qoq_change: pct(newUsers_a, newUsers_qoq),
    newUsers_mom, newUsers_mom_prev, newUsers_mom_change: pct(newUsers_mom, newUsers_mom_prev),

    // Avg engagement time
    avgEngagementTime_a, avgEngagementTime_b, avgEngagementTime_change: pct(avgEngagementTime_a, avgEngagementTime_b),
    avgEngagementTime_qoq, avgEngagementTime_qoq_change: pct(avgEngagementTime_a, avgEngagementTime_qoq),
    avgEngagementTime_mom, avgEngagementTime_mom_prev, avgEngagementTime_mom_change: pct(avgEngagementTime_mom, avgEngagementTime_mom_prev),

    // Key events
    keyEvents_a, keyEvents_b, keyEvents_change: pct(keyEvents_a, keyEvents_b),
    keyEvents_qoq, keyEvents_qoq_change: pct(keyEvents_a, keyEvents_qoq),
    keyEvents_mom, keyEvents_mom_prev, keyEvents_mom_change: pct(keyEvents_mom, keyEvents_mom_prev),

    // Organic sessions
    organicSessions_a, organicSessions_b, organicSessions_change: pct(organicSessions_a, organicSessions_b),
    organicSessions_qoq, organicSessions_qoq_change: pct(organicSessions_a, organicSessions_qoq),
    organicSessions_mom, organicSessions_mom_prev, organicSessions_mom_change: pct(organicSessions_mom, organicSessions_mom_prev),

    // Organic %
    organicPct_a, organicPct_b,
    organicPct_qoq, organicPct_mom, organicPct_mom_prev,

    // Avg organic engagement time
    avgOrganicEngagementTime_a, avgOrganicEngagementTime_b, avgOrganicEngagementTime_change: pct(avgOrganicEngagementTime_a, avgOrganicEngagementTime_b),
    avgOrganicEngagementTime_qoq, avgOrganicEngagementTime_qoq_change: pct(avgOrganicEngagementTime_a, avgOrganicEngagementTime_qoq),
    avgOrganicEngagementTime_mom, avgOrganicEngagementTime_mom_prev, avgOrganicEngagementTime_mom_change: pct(avgOrganicEngagementTime_mom, avgOrganicEngagementTime_mom_prev),

    // Organic engagement rate
    organicEngagementRate_a, organicEngagementRate_b,
    organicEngagementRate_change: pct(organicEngagementRate_a, organicEngagementRate_b),
    organicEngagementRate_qoq,
    organicEngagementRate_qoq_change: pct(organicEngagementRate_a, organicEngagementRate_qoq),
    organicEngagementRate_mom, organicEngagementRate_mom_prev,
    organicEngagementRate_mom_change: pct(organicEngagementRate_mom, organicEngagementRate_mom_prev),

    // *** Organic key events ***
    organicKeyEvents_a, organicKeyEvents_b, organicKeyEvents_change: pct(organicKeyEvents_a, organicKeyEvents_b),
    organicKeyEvents_qoq, organicKeyEvents_qoq_change: pct(organicKeyEvents_a, organicKeyEvents_qoq),
    organicKeyEvents_mom, organicKeyEvents_mom_prev, organicKeyEvents_mom_change: pct(organicKeyEvents_mom, organicKeyEvents_mom_prev),

    // WhatsApp clicks
whatsappClicks_a, whatsappClicks_b, whatsappClicks_change: pct(whatsappClicks_a, whatsappClicks_b),
whatsappClicks_qoq, whatsappClicks_qoq_change: pct(whatsappClicks_a, whatsappClicks_qoq),
whatsappClicks_mom, whatsappClicks_mom_prev, whatsappClicks_mom_change: pct(whatsappClicks_mom, whatsappClicks_mom_prev),

    // Phone clicks
    phoneClicks_a, phoneClicks_b, phoneClicks_change: pct(phoneClicks_a, phoneClicks_b),
    phoneClicks_qoq, phoneClicks_qoq_change: pct(phoneClicks_a, phoneClicks_qoq),
    phoneClicks_mom, phoneClicks_mom_prev, phoneClicks_mom_change: pct(phoneClicks_mom, phoneClicks_mom_prev),

    // Email clicks
    emailClicks_a, emailClicks_b, emailClicks_change: pct(emailClicks_a, emailClicks_b),
    emailClicks_qoq, emailClicks_qoq_change: pct(emailClicks_a, emailClicks_qoq),
    emailClicks_mom, emailClicks_mom_prev, emailClicks_mom_change: pct(emailClicks_mom, emailClicks_mom_prev)
  }
}];

const allItems = $input.all();
const homepageSchemaItem = allItems.find(i => i.json.record_type === 'homepage_schema');
if (!homepageSchemaItem) return [{ json: { error: 'No homepage_schema item found', items: allItems.length, keys: allItems.map(i => Object.keys(i.json)) }}];

const locationsRaw = allItems.find(i => i.json.locations !== undefined)?.json?.locations;
const locationsItem = Array.isArray(locationsRaw)
  ? locationsRaw
  : locationsRaw && typeof locationsRaw === 'object'
    ? Object.values(locationsRaw)
    : [];

// LibreCrawl has already parsed JSON-LD and schema.org markup for every page
// it crawled (raw HTML isn't available from its API at all), so use that
// directly rather than re-extracting from HTML with regex. Both formats are
// included, nothing is filtered out at this stage.
const schemas = [...(homepageSchemaItem.json.json_ld || []), ...(homepageSchemaItem.json.schema_org || [])];

// Flatten @graph arrays
const allSchemas = [];
for (const s of schemas) {
  if (s['@graph']) {
    allSchemas.push(...s['@graph']);
  } else {
    allSchemas.push(s);
  }
}

// Find the business schema. Rather than guessing by @type name (which varies a
// lot between themes/plugins, Yoast commonly outputs "Organization" rather than
// "LocalBusiness", for example), look for whichever schema actually carries
// business-identifying fields, regardless of what it's labelled as. No types
// are excluded from consideration.
const localBusiness =
  allSchemas.find((s) => !!(s.address || s.telephone || s.openingHours || s.openingHoursSpecification || s.geo)) ||
  allSchemas.find((s) => {
    const type = s['@type'] || '';
    const types = Array.isArray(type) ? type : [type];
    return types.includes('LocalBusiness') || types.includes('Organization');
  }) ||
  null;

const result = {
  schema_found: schemas.length > 0,
  schema_count: schemas.length,
  schema_types: allSchemas.map(s => s['@type']).filter(Boolean),
  local_business_schema: !!localBusiness,
  local_business_type: localBusiness?.['@type'] || null,
  has_name: !!localBusiness?.name,
  has_address: !!localBusiness?.address,
  has_telephone: !!localBusiness?.telephone,
  has_opening_hours: !!(localBusiness?.openingHours || localBusiness?.openingHoursSpecification),
  has_geo: !!localBusiness?.geo,
  has_url: !!localBusiness?.url,
  has_image: !!(localBusiness?.image || localBusiness?.logo),
  schema_issues: [],
  gbp_mismatches: []
};

const lb = localBusiness || {};
const addressObj = lb.address || {};
const address = typeof addressObj === 'string' ? addressObj : [
  addressObj.streetAddress,
  addressObj.addressLocality,
  addressObj.addressRegion,
  addressObj.postalCode,
  addressObj.addressCountry
].filter(Boolean).join(', ');

const openingHoursSpec = lb.openingHoursSpecification || [];
const hoursFormatted = Array.isArray(openingHoursSpec) ? openingHoursSpec.map(h => {
  const days = Array.isArray(h.dayOfWeek)
    ? h.dayOfWeek.map(d => d.replace('http://schema.org/', '')).join(', ')
    : (h.dayOfWeek || '').replace('http://schema.org/', '');
  return `${days}: ${h.opens || '?'} - ${h.closes || '?'}`;
}).join(' | ') : lb.openingHours || '';

result.business_name          = lb.name       || null;
result.business_address       = address       || null;
result.business_phone         = lb.telephone  || null;
result.business_opening_hours = hoursFormatted || null;
result.business_logo          = lb.logo || lb.image || null;

// Standard schema issues
if (!result.schema_found) result.schema_issues.push('no_schema_found');
if (!result.local_business_schema) result.schema_issues.push('no_local_business_schema');
if (result.local_business_schema) {
  if (!result.has_name)          result.schema_issues.push('missing_name');
  if (!result.has_address)       result.schema_issues.push('missing_address');
