// Calculate periods dynamically from last 3 complete months
function getLastCompleteMonthEnd() {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), 0); // last day of previous month
}

function monthStart(date) {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

function monthEnd(date) {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0);
}

function addMonths(date, n) {
  return new Date(date.getFullYear(), date.getMonth() + n, 1);
}

function toISO(date) {
  return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
}

// Last complete month = month before current
const m0End   = getLastCompleteMonthEnd();           // Feb 28 2026
const m0Start = monthStart(m0End);                   // Feb 1 2026
const m1End   = monthEnd(addMonths(m0End, -1));      // Jan 31 2026
const m1Start = monthStart(addMonths(m0End, -1));    // Jan 1 2026
const m2End   = monthEnd(addMonths(m0End, -2));      // Dec 31 2025
const m2Start = monthStart(addMonths(m0End, -2));    // Dec 1 2025

// Current period (a) = last 3 complete months
const aStart = m2Start;   // Dec 1 2025
const aEnd   = m0End;     // Feb 28 2026

// YoY prior = same 3 months one year earlier
const bStart = new Date(aStart.getFullYear()-1, aStart.getMonth(), aStart.getDate());
const bEnd   = new Date(aEnd.getFullYear()-1,   aEnd.getMonth(),   aEnd.getDate());

// QoQ prior = 3 months before current period
const qoqEnd   = monthEnd(addMonths(m2End, -1));     // Nov 30 2025
const qoqStart = monthStart(addMonths(m2Start, -3)); // Sep 1 2025

