function combineStats(desk, mob) {
  const hasPrior = !!(desk.has_prior_data || mob.has_prior_data || 
    desk.total_keywords_prior || mob.total_keywords_prior);
  const totalKw      = (desk.total_keywords || 0) + (mob.total_keywords || 0);
  const totalKwPrior = hasPrior ? ((desk.total_keywords_prior || 0) + (mob.total_keywords_prior || 0)) : null;

  const avgRankCombined = (desk.average_rank && mob.average_rank)
    ? Math.round(((desk.average_rank * (desk.total_keywords || 0)) + (mob.average_rank * (mob.total_keywords || 0))) / totalKw * 10) / 10
    : desk.average_rank || mob.average_rank || null;

  const avgRankPrior = hasPrior && (desk.average_rank_prior && mob.average_rank_prior)
    ? Math.round(((desk.average_rank_prior * (desk.total_keywords_prior || 0)) + (mob.average_rank_prior * (mob.total_keywords_prior || 0))) / totalKwPrior * 10) / 10
    : desk.average_rank_prior || mob.average_rank_prior || null;

  return {
    has_prior_data:          hasPrior,
    total_keywords:          totalKw,
    total_keywords_prior:    totalKwPrior,
    average_rank:            avgRankCombined,
    average_rank_prior:      avgRankPrior,
    pos_1_3:                 (desk.pos_1_3 || 0) + (mob.pos_1_3 || 0),
    pos_1_3_prior:           hasPrior ? ((desk.pos_1_3_prior || 0) + (mob.pos_1_3_prior || 0)) : null,
    pos_4_10:                (desk.pos_4_10 || 0) + (mob.pos_4_10 || 0),
    pos_4_10_prior:          hasPrior ? ((desk.pos_4_10_prior || 0) + (mob.pos_4_10_prior || 0)) : null,
    pos_11_20:               (desk.pos_11_20 || 0) + (mob.pos_11_20 || 0),
    pos_11_20_prior:         hasPrior ? ((desk.pos_11_20_prior || 0) + (mob.pos_11_20_prior || 0)) : null,
    pos_21_plus:             (desk.pos_21_plus || 0) + (mob.pos_21_plus || 0),
    above_the_fold:          (desk.above_the_fold || 0) + (mob.above_the_fold || 0),
    above_the_fold_prior:    hasPrior ? ((desk.above_the_fold_prior || 0) + (mob.above_the_fold_prior || 0)) : null,
    ai_share_of_voice:       (desk.ai_share_of_voice || 0) + (mob.ai_share_of_voice || 0),
    ai_share_of_voice_prior: hasPrior ? ((desk.ai_share_of_voice_prior || 0) + (mob.ai_share_of_voice_prior || 0)) : null,
    ai_traffic_value:        (desk.ai_traffic_value || 0) + (mob.ai_traffic_value || 0),
    ai_traffic_value_prior:  hasPrior ? ((desk.ai_traffic_value_prior || 0) + (mob.ai_traffic_value_prior || 0)) : null,
  };
}

