  }

  if (accMobile.top_improvements?.length > 0) {
    lines.push(`Top KW Improvements Mobile (${accPeriod}):\n`);
    accMobile.top_improvements.forEach(k => {
      lines.push(`  - ${k.keyword}: ${k.prior_rank} -> ${k.rank} (+${k.change})\n`);
    });
