  if (accMobile.top_losses?.length > 0) {
    lines.push(`KW Losses Mobile (${accPeriod}):\n`);
    accMobile.top_losses.forEach(k => {
      lines.push(`  - ${k.keyword}: ${k.prior_rank} -> ${k.rank} (${k.change})\n`);
    });
    lines.push(`\n`);
  }

  return lines.join('');
}

// GBP helpers
function sumGbpMetrics(timeSeries, startDate, endDate) {
  const start = new Date(startDate);
  const end   = new Date(endDate);
  const totals = {
    impressions_maps: 0,
    impressions_search: 0,
    direction_requests: 0,
    call_clicks: 0,
    website_clicks: 0
  };

  if (!timeSeries || !Array.isArray(timeSeries)) return totals;

  for (const series of timeSeries) {
    const metric = series.dailyMetric;
    const points = series.timeSeries?.datedValues || [];
    for (const point of points) {
      const d = new Date(`${point.date.year}-${String(point.date.month).padStart(2,'0')}-${String(point.date.day).padStart(2,'0')}`);
      if (d >= start && d <= end) {
        const val = parseInt(point.value || 0, 10);
        if (metric === 'BUSINESS_IMPRESSIONS_DESKTOP_MAPS' || metric === 'BUSINESS_IMPRESSIONS_MOBILE_MAPS') {
          totals.impressions_maps += val;
        } else if (metric === 'BUSINESS_IMPRESSIONS_DESKTOP_SEARCH' || metric === 'BUSINESS_IMPRESSIONS_MOBILE_SEARCH') {
          totals.impressions_search += val;
        } else if (metric === 'BUSINESS_DIRECTION_REQUESTS') {
          totals.direction_requests += val;
        } else if (metric === 'CALL_CLICKS') {
          totals.call_clicks += val;
        } else if (metric === 'WEBSITE_CLICKS') {
          totals.website_clicks += val;
        }
      }
    }
  }

  totals.total_impressions = totals.impressions_maps + totals.impressions_search;
  return totals;
}

function buildGbpSection(gbpApiRaw, periods) {
  const lines = [];
  const ts = gbpApiRaw.multiDailyMetricTimeSeries?.[0]?.dailyMetricTimeSeries || [];

  if (ts.length === 0) {
    lines.push(`No GBP performance data available.\n\n`);
    return lines.join('');
  }

  const a    = sumGbpMetrics(ts, periods.a_start,        periods.a_end);
  const b    = sumGbpMetrics(ts, periods.b_start,        periods.b_end);
  const qoq  = sumGbpMetrics(ts, periods.qoq_start,      periods.qoq_end);
  const mom  = sumGbpMetrics(ts, periods.mom_start,      periods.mom_end);
  const momP = sumGbpMetrics(ts, periods.mom_prev_start,  periods.mom_prev_end);

  function row(label, cur, prior, suffix) {
    return `${label}: ${cur} vs ${prior} ${suffix} (${pctChange(cur, prior) || 'N/A'})\n`;
  }

  lines.push(`--- Year on Year\n`);
  lines.push(row(`Total Impressions`,  a.total_impressions,  b.total_impressions,  'YoY'));
  lines.push(row(`Maps Impressions`,   a.impressions_maps,   b.impressions_maps,   'YoY'));
  lines.push(row(`Search Impressions`, a.impressions_search, b.impressions_search, 'YoY'));
  lines.push(row(`Direction Requests`, a.direction_requests, b.direction_requests, 'YoY'));
  lines.push(row(`Call Clicks`,        a.call_clicks,        b.call_clicks,        'YoY'));
  lines.push(row(`Website Clicks`,     a.website_clicks,     b.website_clicks,     'YoY'));
  lines.push(`\n`);

  lines.push(`--- Quarter on Quarter\n`);
  lines.push(row(`Total Impressions`,  a.total_impressions,  qoq.total_impressions,  'QoQ'));
  lines.push(row(`Maps Impressions`,   a.impressions_maps,   qoq.impressions_maps,   'QoQ'));
  lines.push(row(`Search Impressions`, a.impressions_search, qoq.impressions_search, 'QoQ'));
  lines.push(row(`Direction Requests`, a.direction_requests, qoq.direction_requests, 'QoQ'));
  lines.push(row(`Call Clicks`,        a.call_clicks,        qoq.call_clicks,        'QoQ'));
  lines.push(row(`Website Clicks`,     a.website_clicks,     qoq.website_clicks,     'QoQ'));
  lines.push(`\n`);

  lines.push(`--- Month on Month\n`);
  lines.push(row(`Total Impressions`,  mom.total_impressions,  momP.total_impressions,  'MoM'));
  lines.push(row(`Maps Impressions`,   mom.impressions_maps,   momP.impressions_maps,   'MoM'));
  lines.push(row(`Search Impressions`, mom.impressions_search, momP.impressions_search, 'MoM'));
  lines.push(row(`Direction Requests`, mom.direction_requests, momP.direction_requests, 'MoM'));
  lines.push(row(`Call Clicks`,        mom.call_clicks,        momP.call_clicks,        'MoM'));
  lines.push(row(`Website Clicks`,     mom.website_clicks,     momP.website_clicks,     'MoM'));
  lines.push(`\n`);

  return lines.join('');
}

