// Named page lists, kept to the issues a client actually needs to action against a specific URL
function listUrls(type, label) {
  const rows = issuesOfType(type);
  if (rows.length === 0) return '';
  const out = [`${label}:\n`];
  rows.forEach(r => out.push(`  - ${r.url}\n`));
  out.push(`\n`);
  return out.join('');
}

function listDetails(type, label) {
  const rows = issuesOfType(type);
  if (rows.length === 0) return '';
  const out = [`${label}:\n`];
  rows.forEach(r => out.push(`  - ${r.details}\n`));
  out.push(`\n`);
  return out.join('');
}

// URL plus its detail string on one line, for issues where the detail
// carries context the URL alone doesn't (redirect target, duplicate count,
// word count, missing image list, etc.)
function listUrlsWithDetail(type, label) {
  const rows = issuesOfType(type);
  if (rows.length === 0) return '';
  const out = [`${label}:\n`];
  rows.forEach(r => out.push(`  - ${r.url}${r.details ? ` (${r.details})` : ''}\n`));
  out.push(`\n`);
  return out.join('');
}

