lines.push(`GBP vs Schema Cross-Check: ${schema.gbp_checked ? (schema.gbp_schema_match ? 'All fields match' : `${schema.gbp_mismatches?.length} mismatch(es) found`) : 'Not checked'}\n`);
if (schema.gbp_checked && schema.gbp_mismatches?.length > 0) {
