}
lines.push(`\n`);

lines.push(`6. RANKINGS (ACCURANKER)\n\n`);
lines.push(buildCombinedSection(accDesktop, accMobile));

lines.push(`7. GOOGLE BUSINESS PROFILE\n\n`);
lines.push(buildGbpSection(gbpApiRaw, gbpPeriods));

const fullText = lines.join('');

const requests = [
  {
    insertText: {
      location: { index: 1 },
      text: fullText
    }
  }
];

return [{ json: { requests } }];

// Normalise both sides the same way before comparing - strips protocol, www.,
// a trailing slash, and lower-cases - so a trailing slash or http(s) prefix
// coming from the Clients sheet can never cause a false "Domain not found".
function normalise(d) {
  return String(d || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/+$/, '');
}

const domain = $('Edit Fields').item.json.domain;
const cleanDomain = normalise(domain);

for (const item of $input.all()) {
  if (item.json.domain && normalise(item.json.domain) === cleanDomain) {
    return [{ json: item.json }];
  }
}

// Not tracked in AccuRanker under this domain - fall through with no id rather
// than throwing, so the keyword-fetch nodes downstream can skip gracefully
// instead of building a "domains//keywords" URL and 404ing the whole loop.
console.warn(`AccuRanker: no domain match for "${domain}" - rankings will be skipped for this client this run.`);
return [{ json: { error: 'Domain not found', id: null, domain } }];

const allItems = $input.all();
const byPeriod = (period) =>
  allItems.filter(i => i.json._period === period && i.json.ranks?.length > 0);
// Desktop periods
const currentDesktopItems  = byPeriod('current_desktop');
const priorDesktopItems    = byPeriod('prior_desktop');
const qoqDesktopItems      = byPeriod('qoq_desktop');
const momDesktopItems      = byPeriod('mom_prev_desktop');
const momPrevDesktopItems  = [];
const initialDesktopItems  = byPeriod('initial_desktop');
// Mobile periods
const currentMobileItems   = byPeriod('current_mobile');
const priorMobileItems     = byPeriod('prior_mobile');
const qoqMobileItems       = byPeriod('qoq_mobile');
const momMobileItems       = byPeriod('mom_prev_mobile');
const momPrevMobileItems   = [];
const initialMobileItems   = byPeriod('initial_mobile');
// Parse a period into a keyword array
const parseKeywords = (items) => items.map(i => ({
  keyword: i.json.keyword,
  rank: i.json.ranks[0].rank ?? null,
  above_the_fold: i.json.ranks[0].above_the_fold || false,
  ai_share_of_voice: i.json.ranks[0].ai_share_of_voice || 0,
  ai_traffic_value: i.json.ranks[0].ai_traffic_value || 0,
  search_volume: i.json.search_volume?.search_volume || 0
}));
// Stats helpers
const avgRank = (arr) => {
  const ranked = arr.filter(k => k.rank !== null);
  return ranked.length > 0
    ? Math.round((ranked.reduce((s, k) => s + k.rank, 0) / ranked.length) * 10) / 10
    : null;
};
const countPos = (arr, min, max) => arr.filter(k => k.rank >= min && k.rank <= max).length;
const totalField = (arr, field, round = true) => {
  const v = arr.reduce((s, k) => s + (k[field] || 0), 0);
  return round ? Math.round(v * 100) / 100 : Math.round(v);
};
const buildStats = (arr, hasPrior, priorArr) => {
  const priorMap = {};
  if (hasPrior) priorArr.forEach(k => {
    if (!priorMap[k.keyword] || k.rank < priorMap[k.keyword]) priorMap[k.keyword] = k.rank;
  });
  const changes = hasPrior
    ? arr.filter(k => priorMap[k.keyword] !== undefined).map(k => ({
        keyword: k.keyword,
        rank: k.rank,
        prior_rank: priorMap[k.keyword],
        change: priorMap[k.keyword] - k.rank
      }))
    : [];
  return {
    total_keywords:          arr.length,
    total_keywords_prior:    hasPrior ? priorArr.length : null,
    average_rank:            avgRank(arr),
    average_rank_prior:      hasPrior ? avgRank(priorArr) : null,
    pos_1_3:                 countPos(arr, 1, 3),
    pos_1_3_prior:           hasPrior ? countPos(priorArr, 1, 3) : null,
    pos_4_10:                countPos(arr, 4, 10),
    pos_4_10_prior:          hasPrior ? countPos(priorArr, 4, 10) : null,
    pos_11_20:               countPos(arr, 11, 20),
    pos_11_20_prior:         hasPrior ? countPos(priorArr, 11, 20) : null,
    pos_21_plus:             countPos(arr, 21, 9999),
    above_the_fold:          arr.filter(k => k.above_the_fold).length,
    above_the_fold_prior:    hasPrior ? priorArr.filter(k => k.above_the_fold).length : null,
    ai_share_of_voice:       totalField(arr, 'ai_share_of_voice'),
    ai_share_of_voice_prior: hasPrior ? totalField(priorArr, 'ai_share_of_voice') : null,
    ai_traffic_value:        totalField(arr, 'ai_traffic_value', false),
    ai_traffic_value_prior:  hasPrior ? totalField(priorArr, 'ai_traffic_value', false) : null,
    top_10_keywords:         [...arr].sort((a, b) => a.rank - b.rank).slice(0, 10),
    top_improvements:        changes.filter(k => k.change > 0).sort((a, b) => b.change - a.change).slice(0, 5),
    top_losses:              changes.filter(k => k.change < 0).sort((a, b) => a.change - b.change).slice(0, 5),
    has_prior_data:          hasPrior
  };
};
// Build stats for a device (desktop or mobile)
const buildDevice = (currentItems, priorItems, qoqItems, momItems, momPrevItems, initialItems) => {
  const current  = parseKeywords(currentItems);
  const prior    = parseKeywords(priorItems);
  const qoq      = parseKeywords(qoqItems);
  const mom      = parseKeywords(momItems);
  const momPrev  = parseKeywords(momPrevItems);
  // Debug
  console.log('QoQ items count:', qoqItems.length);
  console.log('First QoQ rank:', qoqItems[0]?.json?.ranks?.[0]?.rank);
  console.log('First current rank:', currentItems[0]?.json?.ranks?.[0]?.rank);
  const currentRankMap = {};
  current.forEach(k => currentRankMap[k.keyword] = k.rank);
  const isDifferent = (priorArr) =>
    priorArr.some(k => currentRankMap[k.keyword] !== undefined &&
                       currentRankMap[k.keyword] !== k.rank);
  const hasYoY     = prior.length > 0 && isDifferent(prior);
  const hasQoQ     = qoq.length > 0;
  const hasMoM     = mom.length > 0;
  const hasMomPrev = momPrev.length > 0;
  // Initial fallback if no YoY
  const hasInitial = initialItems.some(i => i.json.initial_rank?.rank !== undefined);
  let initialFallback = [];
  if (!hasYoY && hasInitial) {
    initialFallback = initialItems
      .filter(i => i.json.initial_rank?.rank !== undefined)
      .map(i => ({
        keyword: i.json.keyword,
        rank: i.json.initial_rank.rank,
        above_the_fold: false,
        ai_share_of_voice: i.json.initial_rank.share_of_voice || 0,
        ai_traffic_value: 0,
        search_volume: i.json.search_volume?.search_volume || 0
      }));
  }
  const initialDate = !hasYoY && hasInitial
    ? initialItems.find(i => i.json.initial_rank?.created_at)?.json.initial_rank.created_at
    : null;
  const initialDateLabel = initialDate
    ? new Date(initialDate).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' })
    : null;
  const yoyPrior = hasYoY ? prior : (hasInitial ? initialFallback : []);
  const yoyHas   = hasYoY || hasInitial;
  const yoyLabel = hasYoY ? 'YoY' : 'Initial';
  return {
    period_label: yoyLabel,
    initial_date: initialDateLabel,
    ...buildStats(current, yoyHas, yoyPrior),
    qoq:       buildStats(current, hasQoQ, qoq),
    mom:       buildStats(current, hasMoM, mom),
    mom_delta: buildStats(mom, hasMomPrev, momPrev),
  };
};
return [{
  json: {
    desktop: buildDevice(
      currentDesktopItems, priorDesktopItems, qoqDesktopItems,
      momDesktopItems, momPrevDesktopItems, initialDesktopItems
    ),
    mobile: buildDevice(
      currentMobileItems, priorMobileItems, qoqMobileItems,
      momMobileItems, momPrevMobileItems, initialMobileItems
    )
  }
}];

