const domain = $('Edit Fields').first().json.domain;
const locations = $input.first().json.locations;

const stripUtm = url => url ? decodeURIComponent(url).split('?')[0].split('#')[0] : '';

// Not every client has a GBP (Google Business Profile) listing, and some
// clients' accounts return no locations at all. Rather than throwing (which
// would kill this client's whole run), fall through to a null placeholder
// that flows down the same chain into Merge All Data - Performance data GBP
// and Performance API code node already handle missing/error data safely.
const match = Array.isArray(locations)
  ? locations.find(loc => loc.websiteUri && stripUtm(loc.websiteUri).includes(domain))
  : null;

if (!match) {
  return [{ json: {
    locationId: null,
    locationName: null,
    title: null,
    domain: domain,
    gbp_available: false
  }}];
}

return [{ json: {
  locationId: match.name.replace('locations/', ''),
  locationName: match.name,
  title: match.title,
  domain: domain,
  gbp_available: true
}}];

const raw = $input.first().json;
const unwrapped = Array.isArray(raw) ? raw[0] : raw;

return [{ json: { gbp_raw: JSON.stringify(unwrapped) } }];

// Simple, dependency-free SEO crawl node.
// Covers: 404s, 5xx errors, 301/302 redirects, missing alt text (real
// content images only, tracking pixels excluded), JSON-LD/schema.org
// presence, missing/duplicate titles & meta descriptions, missing
// canonical, H1/H2 structure, missing viewport, and thin content.
// Uses plain HTTP requests only — no JavaScript rendering, no headless
// browser — identifies honestly as Screaming Frog's UA, which is what
// gets past WAFs that block browser-impersonating bot traffic.
//
// Output shape matches what Build Doc Content already expects:
// record_type: 'page_summary' | 'issue' | 'homepage_schema'

const domain = $('Edit Fields').first().json.domain;
const baseUrl = 'https://' + domain;
const MAX_URLS = 300;      // safety cap
const CONCURRENCY = 3;     // gentle, matches what worked in testing
const REQUEST_DELAY_MS = 500;
const THIN_CONTENT_WORD_COUNT = 300;
const EXCLUDE_PATTERNS = ['/blog/*', '/news/*', '/wp-content/*'];
const THIN_CONTENT_EXEMPT_PATTERNS = ['/privacy-policy', '/cookie-policy', '/terms', '/terms-conditions'];

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// --- helpers -----------------------------------------------------------

const isExcluded = (url) => {
  return EXCLUDE_PATTERNS.some((pattern) => {
    const prefix = pattern.replace(/\*$/, ''); // strip trailing wildcard
    return url.includes(prefix);
  });
};

const isThinContentExempt = (url) => {
  return THIN_CONTENT_EXEMPT_PATTERNS.some((pattern) => url.includes(pattern));
};

// n8n's Code node sandbox doesn't expose the global URL class, so pull the
// path out with a regex instead of new URL(url).pathname.
const getPathname = (u) => {
  const match = (u || '').match(/^https?:\/\/[^/]+(\/[^?#]*)?/i);
  return match && match[1] ? match[1] : '/';
};

const fetchRaw = async (url) => {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Screaming Frog SEO Spider/24.3',
        Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      },
      followRedirect: false,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 15000,
    });
    return resp;
  } catch (e) {
    return { statusCode: 0, headers: {}, body: '', __error: e.message };
  }
};

// Discover URLs by following real internal links from the homepage
// (breadth-first), the same way Screaming Frog crawls by default — so
// orphaned URLs with no live inlinks (old sitemap entries, dead pages)
// never get included in the first place.
const discoverUrls = async () => {
  const siteHost = (baseUrl.match(/^https?:\/\/([^/]+)/i)?.[1] || '').toLowerCase().replace(/^www\./, '');
  const ASSET_EXT = /\.(jpg|jpeg|png|gif|svg|webp|ico|css|js|woff2?|ttf|eot|zip|mp4|mp3)(\?|#|$)/i;

  const getHost = (u) => (u.match(/^https?:\/\/([^/]+)/i)?.[1] || '').toLowerCase().replace(/^www\./, '');

  const resolveUrl = (base, href) => {
    if (!href) return null;
    href = href.trim();
    if (!href || /^(mailto:|tel:|javascript:|#)/i.test(href)) return null;
    let resolved;
    if (/^https?:\/\//i.test(href)) {
      resolved = href;
    } else if (href.startsWith('//')) {
      resolved = 'https:' + href;
    } else if (href.startsWith('/')) {
      const originMatch = base.match(/^(https?:\/\/[^/]+)/i);
      resolved = (originMatch ? originMatch[1] : base) + href;
    } else {
      const dir = base.replace(/[^/]*$/, '');
      resolved = dir + href;
    }
    resolved = resolved.split('#')[0];
    while (/\/[^/]+\/\.\.\//.test(resolved)) {
      resolved = resolved.replace(/\/[^/]+\/\.\.\//, '/');
    }
    return resolved.replace(/\/\.\//g, '/');
  };

  const extractLinks = (html, pageUrl) => {
    const hrefs = [...html.matchAll(/<a\b[^>]*\bhref\s*=\s*("([^"]*)"|'([^']*)')/gi)]
      .map((m) => (m[2] !== undefined ? m[2] : m[3]));
    const out = [];
    for (const href of hrefs) {
      const resolved = resolveUrl(pageUrl, href);
      if (!resolved) continue;
      if (getHost(resolved) !== siteHost) continue;
      if (ASSET_EXT.test(resolved)) continue;
      out.push(resolved);
    }
    return out;
  };

  const visited = new Set();
  const queue = [baseUrl + '/'];
  const discovered = [];

  while (queue.length > 0 && discovered.length < MAX_URLS) {
    const url = queue.shift();
    const key = normalise(url);
    if (visited.has(key)) continue;
    visited.add(key);
    if (isExcluded(url)) continue;

    discovered.push(url);

    const resp = await fetchRaw(url);
    if (resp.statusCode === 200 && typeof resp.body === 'string') {
      const links = extractLinks(resp.body, url);
      for (const link of links) {
        if (!visited.has(normalise(link))) queue.push(link);
      }
    }
    await sleep(REQUEST_DELAY_MS);
  }

  return discovered;
};

// Returns an array of image src URLs (or a placeholder) for every <img>
// missing usable alt text, rather than just a count.
const extractImagesMissingAlt = (html) => {
  const imgTags = html.match(/<img\b[^>]*>/gi) || [];
  const missing = [];
  for (const tag of imgTags) {
    const altMatch = tag.match(/\balt\s*=\s*("([^"]*)"|'([^']*)')/i);
    const altValue = altMatch ? (altMatch[2] !== undefined ? altMatch[2] : altMatch[3]) : null;
    const isMissing = !altMatch || !altValue || !altValue.trim();
    if (isMissing) {
      const srcMatch = tag.match(/\bsrc\s*=\s*("([^"]*)"|'([^']*)')/i);
      const src = srcMatch ? (srcMatch[2] !== undefined ? srcMatch[2] : srcMatch[3]) : '(no src attribute)';
      missing.push(src);
    }
  }
  return missing;
};

const stripJsonComments = (str) => {
  return str
    .replace(/\/\*[\s\S]*?\*\//g, '')   // block comments
    .replace(/^[ \t]*\/\/.*$/gm, '');   // whole-line // comments only
};

const extractJsonLd = (html) => {
  const blocks = [...html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
  const parsed = [];
  for (const b of blocks) {
    const cleaned = stripJsonComments(b[1].trim());
    try {
      parsed.push(JSON.parse(cleaned));
    } catch (e) {
      // skip malformed JSON-LD rather than failing the whole crawl
    }
  }
  return parsed;
};

const extractTag = (html, regex) => {
  const m = html.match(regex);
  return m ? m[1].trim() : '';
};

const hasCanonical = (html) => {
  const linkTags = html.match(/<link\b[^>]*>/gi) || [];
  return linkTags.some(
    (tag) => /rel\s*=\s*["']canonical["']/i.test(tag) && /href\s*=\s*["'][^"']+["']/i.test(tag)
  );
};

const hasViewport = (html) => {
  const metaTags = html.match(/<meta\b[^>]*>/gi) || [];
  return metaTags.some((tag) => /name\s*=\s*["']viewport["']/i.test(tag));
};

const countTags = (html, tagName) => (html.match(new RegExp(`<${tagName}\\b[^>]*>`, 'gi')) || []).length;

const getWordCount = (html) => {
  const stripped = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|&amp;|&lt;|&gt;|&quot;|&#\d+;/g, ' ');
  return stripped.split(/\s+/).filter(Boolean).length;
};

const normalise = (u) => (u || '').replace(/\/+$/, '').toLowerCase();

// --- main crawl ----------------------------------------------------------

const urls = await discoverUrls();
const results = [];
let homepageEntry = null;

const crawlOne = async (url) => {
  await sleep(REQUEST_DELAY_MS);
  const resp = await fetchRaw(url);
  const status = resp.statusCode || 0;

  const record = {
    record_type: 'page_summary',
    url,
    statusCode: status,
    title: '',
    meta_desc: '',
    images_without_alt: 0,
    images_missing_alt_urls: [],
    has_structured_data: false,
    has_canonical: false,
    has_viewport: false,
    h1_count: 0,
    h2_count: 0,
    word_count: 0,
    issue_count: 0,
    has_issues: false,
  };

  const issues = [];

  if (status === 301 || status === 302) {
    const location = resp.headers.location || resp.headers.Location || '';
    issues.push({
      type: 'warning',
      category: 'Technical',
      issue: status === 301 ? '301_redirect' : '302_redirect',
      details: `Redirects to ${location || '(no Location header)'}`,
      todoist_priority: 3,
    });
  } else if (status >= 300 && status < 400) {
    const location = resp.headers.location || resp.headers.Location || '';
    issues.push({
      type: 'warning',
      category: 'Technical',
      issue: `${status}_redirect`,
      details: `Redirects to ${location || '(no Location header)'}`,
      todoist_priority: 3,
    });
  } else if (status === 404) {
    issues.push({
      type: 'error',
      category: 'Technical',
      issue: '404',
      details: 'Page returns a 404 error',
      todoist_priority: 4,
    });
  } else if (status >= 500) {
    issues.push({
      type: 'error',
      category: 'Technical',
      issue: '5xx_error',
      details: `Page returns a ${status} server error`,
      todoist_priority: 4,
    });
  } else if (status === 200 && resp.body) {
    const html = resp.body.toString();
    const htmlForImages = html.replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');

    record.title = extractTag(html, /<title[^>]*>([\s\S]*?)<\/title>/i);
    record.meta_desc = extractTag(
      html,
      /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i
    );
    record.images_missing_alt_urls = extractImagesMissingAlt(htmlForImages);
    record.images_without_alt = record.images_missing_alt_urls.length;
    const jsonLd = extractJsonLd(html);
    record.has_structured_data = jsonLd.length > 0;
    record.has_canonical = hasCanonical(html);
    record.has_viewport = hasViewport(html);
    record.h1_count = countTags(html, 'h1');
    record.h2_count = countTags(html, 'h2');
    record.word_count = getWordCount(html);

    if (!record.title) {
      issues.push({
        type: 'error',
        category: 'On-Page',
        issue: 'missing_title',
        details: 'Page has no <title> tag',
        todoist_priority: 4,
      });
    }
    if (!record.meta_desc) {
      issues.push({
        type: 'warning',
        category: 'On-Page',
        issue: 'missing_meta',
        details: 'Page has no meta description',
        todoist_priority: 3,
      });
    }
    if (!record.has_canonical) {
      issues.push({
        type: 'warning',
        category: 'Technical',
        issue: 'missing_canonical',
        details: 'Page has no canonical tag',
        todoist_priority: 3,
      });
    }
    if (!record.has_viewport) {
      issues.push({
        type: 'warning',
        category: 'Technical',
        issue: 'missing_viewport',
        details: 'Page has no viewport meta tag',
        todoist_priority: 3,
      });
    }
    if (record.h1_count > 1) {
      issues.push({
        type: 'warning',
        category: 'On-Page',
        issue: 'multiple_h1',
        details: `Page has ${record.h1_count} H1 tags`,
        todoist_priority: 2,
      });
    }
    if (record.h2_count === 0) {
      issues.push({
        type: 'warning',
        category: 'On-Page',
        issue: 'missing_h2',
        details: 'Page has no H2 subheadings',
        todoist_priority: 2,
      });
    }
    if (record.word_count < THIN_CONTENT_WORD_COUNT && !isThinContentExempt(url)) {
      issues.push({
        type: 'warning',
        category: 'Content',
        issue: 'thin_content',
        details: `Page has only ${record.word_count} words (under ${THIN_CONTENT_WORD_COUNT})`,
        todoist_priority: 2,
      });
    }
    if (record.images_without_alt > 0) {
      issues.push({
        type: 'warning',
        category: 'Accessibility',
        issue: 'images_missing_alt',
        details: `${record.images_without_alt} image(s) missing alt text: ${record.images_missing_alt_urls.slice(0, 10).join(', ')}${record.images_missing_alt_urls.length > 10 ? ` (+${record.images_missing_alt_urls.length - 10} more)` : ''}`,
        todoist_priority: 2,
      });
    }
    if (!record.has_structured_data) {
      issues.push({
        type: 'error',
        category: 'Structured Data',
        issue: 'no_structured_data',
        details: 'Page has no JSON-LD schema markup',
        todoist_priority: 3,
      });
    }

    if (getPathname(url) === '/') {
      homepageEntry = { url, json_ld: jsonLd, schema_org: [] };
    }
  } else if (status === 0) {
    issues.push({
      type: 'error',
      category: 'Technical',
      issue: 'request_failed',
      details: resp.__error || 'Could not fetch page',
      todoist_priority: 4,
    });
  }

  record.issue_count = issues.length;
  record.has_issues = issues.length > 0;

  results.push({ json: record });
  for (const issue of issues) {
    results.push({ json: { record_type: 'issue', url, ...issue } });
  }
};

// simple concurrency pool
let index = 0;
const workers = Array.from({ length: CONCURRENCY }, async () => {
  while (index < urls.length) {
    const i = index++;
    await crawlOne(urls[i]);
  }
});
await Promise.all(workers);

// --- cross-page checks: duplicate titles & meta descriptions -------------

const titleGroups = new Map();
const metaGroups = new Map();

for (const r of results) {
  if (r.json.record_type !== 'page_summary') continue;
  const t = (r.json.title || '').trim().toLowerCase();
  const m = (r.json.meta_desc || '').trim().toLowerCase();
  if (t) {
    if (!titleGroups.has(t)) titleGroups.set(t, []);
    titleGroups.get(t).push(r.json.url);
  }
  if (m) {
    if (!metaGroups.has(m)) metaGroups.set(m, []);
    metaGroups.get(m).push(r.json.url);
  }
}

for (const urlsForTitle of titleGroups.values()) {
  if (urlsForTitle.length < 2) continue;
  for (const u of urlsForTitle) {
    results.push({
      json: {
        record_type: 'issue',
        url: u,
        type: 'warning',
        category: 'On-Page',
        issue: 'duplicate_title',
        details: `Title is duplicated across ${urlsForTitle.length} pages`,
        todoist_priority: 3,
      },
    });
  }
}

for (const urlsForMeta of metaGroups.values()) {
  if (urlsForMeta.length < 2) continue;
  for (const u of urlsForMeta) {
    results.push({
      json: {
        record_type: 'issue',
        url: u,
        type: 'warning',
        category: 'On-Page',
        issue: 'duplicate_meta',
        details: `Meta description is duplicated across ${urlsForMeta.length} pages`,
        todoist_priority: 2,
      },
    });
  }
}

if (homepageEntry) {
  results.push({ json: { record_type: 'homepage_schema', ...homepageEntry } });
}

return results

// Turn the model's markdown reply into styled HTML for the email body.
const aiItem = $input.first().json;
const errRaw = aiItem.error || (aiItem.message && aiItem.message.error) || null;
const aiError = (errRaw && typeof errRaw === 'object') ? (errRaw.message || JSON.stringify(errRaw)) : errRaw;
// Claude's Messages API returns { content: [ { type: 'text', text: '...' } ] }.
// The message.content / response / text checks are kept as a fallback in
// case this ever points at a different (e.g. Ollama-shaped) endpoint again.
let raw = (Array.isArray(aiItem.content) && aiItem.content[0] && aiItem.content[0].text)
  || (aiItem.message && aiItem.message.content)
  || aiItem.response
  || aiItem.text
  || '';

// The Qwen/Ollama call has onError: continueRegularOutput so a failed or
// oversized request never crashes this client's run - but that also meant
// a failure used to produce a silently blank email with no clue why. Make
// the failure visible instead, so a blank summary is never mistaken for a
// clean run with nothing to say.
if (!raw) {
  raw = aiError
    ? `## AI Summary Unavailable\n\nThe AI summary could not be generated for this client: ${aiError}\n\nThe rest of this audit (data, doc, dashboard log) still completed normally - check the Claude node's output for this client's run and re-run the summary if needed.`
    : '## AI Summary Unavailable\n\nThe AI returned an empty response for this client. This usually means the request hit a rate limit or auth issue, or the Claude API was briefly unreachable. Check the Claude node\'s output for this client\'s run.';
}

function escapeHtml(s) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function inlineFormat(line) {
  line = line.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  line = line.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1<em>$2</em>');
  return line;
}

function mdToHtml(md) {
  const lines = escapeHtml(md).split('\n');
  let html = '';
  let inUl = false;
  let inOl = false;

  const closeLists = () => {
    if (inUl) { html += '</ul>'; inUl = false; }
    if (inOl) { html += '</ol>'; inOl = false; }
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();

    if (line === '') { closeLists(); continue; }

    if (/^(\*\*\*+|---+)$/.test(line)) {
      closeLists();
      html += '<hr style="border:none;border-top:1px solid #ddd;margin:24px 0;">';
      continue;
    }

    let m;
    if ((m = line.match(/^######\s+(.*)$/))) { closeLists(); html += `<h6 style="margin:18px 0 6px;">${inlineFormat(m[1])}</h6>`; continue; }
    if ((m = line.match(/^#####\s+(.*)$/)))  { closeLists(); html += `<h5 style="margin:18px 0 6px;">${inlineFormat(m[1])}</h5>`; continue; }
    if ((m = line.match(/^####\s+(.*)$/)))   { closeLists(); html += `<h4 style="margin:18px 0 6px;">${inlineFormat(m[1])}</h4>`; continue; }
    if ((m = line.match(/^###\s+(.*)$/)))    { closeLists(); html += `<h3 style="margin:22px 0 8px;color:#1a1a1a;">${inlineFormat(m[1])}</h3>`; continue; }
    if ((m = line.match(/^##\s+(.*)$/)))     { closeLists(); html += `<h2 style="margin:24px 0 10px;color:#1a1a1a;">${inlineFormat(m[1])}</h2>`; continue; }
    if ((m = line.match(/^#\s+(.*)$/)))      { closeLists(); html += `<h1 style="margin:24px 0 10px;color:#1a1a1a;">${inlineFormat(m[1])}</h1>`; continue; }

    if ((m = line.match(/^\d+\.\s+(.*)$/))) {
      if (!inUl && !inOl) { html += '<ol style="margin:8px 0;padding-left:22px;">'; inOl = true; }
      else if (inUl) { closeLists(); html += '<ol style="margin:8px 0;padding-left:22px;">'; inOl = true; }
      html += `<li style="margin-bottom:4px;">${inlineFormat(m[1])}</li>`;
      continue;
    }

    if ((m = line.match(/^[-*]\s+(.*)$/))) {
      if (!inOl && !inUl) { html += '<ul style="margin:8px 0;padding-left:22px;">'; inUl = true; }
      else if (inOl) { closeLists(); html += '<ul style="margin:8px 0;padding-left:22px;">'; inUl = true; }
      html += `<li style="margin-bottom:4px;">${inlineFormat(m[1])}</li>`;
      continue;
    }

    closeLists();
    html += `<p style="margin:10px 0;">${inlineFormat(line)}</p>`;
  }

  closeLists();
  return html;
}

const bodyHtml = mdToHtml(raw);

const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#222222;max-width:680px;">${bodyHtml}</div>`;

return [{ json: { html, raw } }];

// Compact per-client snapshot for the dashboard. Runs in parallel to
// "Build Doc Content" off the same "Merge All Data" input, so it can never
// affect the existing Google Doc / email pipeline.
const items = $input.all();

const client = $('Edit Fields').first().json;

const ga4 = items.find(i => i.json.sessions_a !== undefined)?.json || {};

const findGscTotals = (period) =>
  items.find(i => i.json.gsc_period === period)?.json?.rows?.[0] || {};
const gscA = findGscTotals('current');
const gscB = findGscTotals('yoy');

const speedMobile  = items.find(i => i.json.lighthouseResult !== undefined)?.json || {};
const speedDesktop = items.filter(i => i.json.lighthouseResult !== undefined)?.[1]?.json || {};
const perfScore = (r) => {
  const s = r?.lighthouseResult?.categories?.performance?.score;
  return (s === undefined || s === null) ? null : Math.round(s * 100);
};

const accurankerRaw = items.find(i => i.json.desktop !== undefined && i.json.mobile !== undefined)?.json || {};
const accDesktop = accurankerRaw.desktop || {};
const accMobile  = accurankerRaw.mobile  || {};

const pageSummaries = items.filter(i => i.json.record_type === 'page_summary').map(i => i.json);
const crawlIssues   = items.filter(i => i.json.record_type === 'issue').map(i => i.json);

return [{
  json: {
    run_date: new Date().toISOString().split('T')[0],
    client_name: client.client_name,
    domain: client.domain,

    sessions_current: ga4.sessions_a ?? null,
    sessions_yoy: ga4.sessions_b ?? null,
    organic_sessions_current: ga4.organicSessions_a ?? null,
    organic_sessions_yoy: ga4.organicSessions_b ?? null,
    leads_current: ga4.keyEvents_a ?? null,
    leads_yoy: ga4.keyEvents_b ?? null,
    organic_leads_current: ga4.organicKeyEvents_a ?? null,
    organic_leads_yoy: ga4.organicKeyEvents_b ?? null,

    gsc_clicks_current: gscA.clicks ?? null,
    gsc_clicks_yoy: gscB.clicks ?? null,
    gsc_impressions_current: gscA.impressions ?? null,
    gsc_avg_position_current: gscA.position ?? null,
    gsc_avg_position_yoy: gscB.position ?? null,

    pagespeed_mobile_score: perfScore(speedMobile),
    pagespeed_desktop_score: perfScore(speedDesktop),

    accuranker_avg_rank_desktop: accDesktop.average_rank ?? null,
    accuranker_top3_desktop: accDesktop.pos_1_3 ?? null,
    accuranker_top10_desktop: (accDesktop.pos_1_3 ?? 0) + (accDesktop.pos_4_10 ?? 0),
    accuranker_avg_rank_mobile: accMobile.average_rank ?? null,

    pages_crawled: pageSummaries.length,
    pages_with_issues: pageSummaries.filter(p => p.has_issues).length,
    crawl_issue_count: crawlIssues.length,
  }
}];
